library(rstan)
d <- read.csv('/app/data.csv')
stan_data <- list(N=nrow(d), y=d$y, n=d$n)
mod <- stan_model(file='/app/hierarchical_model.stan')  # or stan()
fit <- sampling(mod, data=stan_data, chains=4, iter=100000, seed=1, cores=4, refresh=0)
samples <- rstan::extract(fit, pars=c('alpha','beta'))
writeLines(sprintf("%.10f", mean(samples$alpha)), '/app/posterior_alpha_mean.txt')
writeLines(sprintf("%.10f", mean(samples$beta)), '/app/posterior_beta_mean.txt')

